import{_ as t,o as s,c as o,a5 as r}from"./chunks/framework.DJo0M80U.js";const l=JSON.parse(`{"title":"重定向和别名","description":"重定向 重定向也是通过 routes 配置来完成，下面例子是从 /home 重定向到 /： const routes [\\\\{ path: '/home', redirect: '/' \\\\}] 重定向的目标也可以是一个命名的路由： const routes [\\\\{ path: '/。","frontmatter":{"title":"重定向和别名","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","路由与状态管理"],"description":"重定向 重定向也是通过 routes 配置来完成，下面例子是从 /home 重定向到 /： const routes [\\\\{ path: '/home', redirect: '/' \\\\}] 重定向的目标也可以是一个命名的路由： const routes [\\\\{ path: '/。","sidebarWeight":65,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/vueRouter/重定向和别名.md"},"headers":[],"relativePath":"posts/Vue系统教程/04-路由与状态管理/重定向和别名.md","filePath":"posts/Vue系统教程/04-路由与状态管理/重定向和别名.md"}`),a={name:"posts/Vue系统教程/04-路由与状态管理/重定向和别名.md"};function p(n,e,c,i,u,h){return s(),o("div",null,[...e[0]||(e[0]=[r('<div><h1 id="重定向和别名" tabindex="-1">重定向和别名 <a class="header-anchor" href="#重定向和别名" aria-label="Permalink to &quot;重定向和别名&quot;">​</a></h1><blockquote><p>本节目标：理解“重定向和别名”的核心思路，并能把它用于实际开发或面试表达。 <strong>重定向</strong> 重定向也是通过 routes 配置来完成，下面例子是从 /home 重定向到 /： const routes = [{ path: &#39;/home&#39;, redirect: &#39;/&#39; }]</p></blockquote><p>重定向的目标也可以是一个命名的路由： const routes = [{ path: &#39;/home&#39;, redirect: { name: &#39;homepage&#39; } }]</p><p>甚至是一个方法，动态返回重定向目标： const routes = [ { // /search/screens -&gt; /search?q=screens path: &#39;/search/:searchText&#39;, redirect: to =&gt; { // 方法接收目标路由作为参数 // return 重定向的字符串路径/路径对象 return { path: &#39;/search&#39;, query: { q: to.params.searchText } } }, }, { path: &#39;/search&#39;, // ... }, ] 请注意，导航守卫并没有应用在跳转路由上，而仅仅应用在其目标上。在上面的例子中，在 /home 路由中添加 beforeEnter 守卫不会有任何效果。</p><p>在写 redirect 的时候，可以省略 component 配置，因为它从来没有被直接访问过，所以没有组件要渲染。</p><p>唯一的例外是嵌套路由：如果一个路由记录有 children 和 redirect 属性，它也应该有 component 属性。</p><p><strong>相对重定向</strong> 也可以重定向到相对位置： const routes = [ { // 将总是把/users/123/posts重定向到/users/123/profile。 path: &#39;/users/:id/posts&#39;, redirect: to =&gt; { // 该函数接收目标路由作为参数 // 相对位置不以<code>/</code>开头 // 或 { path: &#39;profile&#39;} return &#39;profile&#39; }, }, ]</p><p><strong>别名</strong> 重定向是指当用户访问 /home 时，URL 会被 / 替换，然后匹配成 /。那么什么是别名呢？ 将 / 别名为 /home，意味着当用户访问 /home 时，URL 仍然是 /home，但会被匹配为用户正在访问 /。</p><p>上面对应的路由配置为： const routes = [{ path: &#39;/&#39;, component: Homepage, alias: &#39;/home&#39; }] 通过别名，你可以自由地将 UI 结构映射到一个任意的 URL，而不受配置的嵌套结构的限制。使别名以 / 开头，以使嵌套路径中的路径成为绝对路径。你甚至可以将两者结合起来，用一个数组提供多个别名： js const routes = [ { path: &#39;/users&#39;, component: UsersLayout, children: [ // 为这 3 个 URL 呈现 UserList // - /users // - /users/list // - /people { path: &#39;&#39;, component: UserList, alias: [&#39;/people&#39;, &#39;list&#39;] }, ], }, ]</p><p>如果你的路由有参数，请确保在任何绝对别名中包含它们： const routes = [ { path: &#39;/users/:id&#39;, component: UsersByIdLayout, children: [ // 为这 3 个 URL 呈现 UserDetails // - /users/24 // - /users/24/profile // - /24 { path: &#39;profile&#39;, component: UserDetails, alias: [&#39;/:id&#39;, &#39;&#39;] }, ], }, ] 关于 SEO 的注意事项: 使用别名时，一定要定义规范链接.</p></div>',1)])])}const m=t(a,[["render",p]]);export{l as __pageData,m as default};
